 @Override void schema(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,type TEXT,date TEXT,payload TEXT)");db.execSQL("CREATE TABLE IF NOT EXISTS wiki_queue(id TEXT PRIMARY KEY,version INTEGER NOT NULL,operation TEXT NOT NULL)");}
 @Override void put(SQLiteDatabase db,JSONObject r)throws Exception{db.execSQL("INSERT OR REPLACE INTO records(id,type,date,payload) VALUES(?,?,?,?)",new Object[]{r.getString("id"),r.optString("type"),r.optString("date"),r.toString()});}
 JSONObject mock(String task,JSONObject input)throws Exception{
  requests++;if(task.equals("merge_information_units"))return new JSONObject().put("groups",new JSONArray());
  JSONArray out=new JSONArray(),blocks=input.getJSONArray("blocks");for(int i=0;i<blocks.length();i++){JSONObject b=blocks.getJSONObject(i);JSONArray units=new JSONArray();for(String text:b.getString("text").split("[。\\n]+")){text=text.trim();if(!text.isEmpty())units.put(text.length()>230?text.substring(0,220):text);}out.put(new JSONObject().put("id",b.getString("id")).put("units",units));}return new JSONObject().put("blocks",out);
 }
 void finishNote(SQLiteDatabase db,JSONObject r,InformationUnits.Model model)throws Exception{for(int i=0;i<1000&&!InformationUnits.current(get(db,r.getString("id")));i++)InformationUnits.step(db,r,model);check(InformationUnits.current(get(db,r.getString("id"))),"Saved source completes: "+r.getString("id"));}
