  JSONObject updated=get(db,"cache");updated.put("updatedAt",11).put("note","第一段定义。\n\n第二段修改。\n\n第三段结论。");put(db,updated);int before=requests;finishNote(db,updated,this::mock);q=get(db,"cache").getJSONObject("informationUnits");check(q.getInt("reusedBlocks")==2&&q.getInt("count")==3&&requests-before==2,"Editing one paragraph reuses two and replaces the old count");check(!q.getJSONArray("units").toString().contains("第二段方法"),"Edited-away information is removed");
